window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-43d73a9ef2920dba"]={"versions": [{"id": "FIG-43d73a9ef2920dba", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Kontext der AUTOSAR-E2E-Protokollspezifikation (End-to-End Communication Protection Library). Das Diagramm spezifiziert den detaillierten Teilschritt „Increment Counter“ innerhalb der Ablauffunktionen <code>E2E_P07Protect()</code> und <code>E2E_P07Forward()</code> für das E2E-Profil 7.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Initialknoten &amp; Endknoten:</strong> Startpunkt (Initial Node) und Terminierungspunkt (Activity Final Node) der Aktivität.\n</li><li><strong>Aktion:</strong> <code>State-&gt;Counter++</code> repräsentiert die Modifikation des Zählerzustands in der Zustandsstruktur <code>E2E_P07ProtectStateType</code>.\n</li><li><strong>Kommentar/Notiz:</strong> Assoziierte Notiz an der Aktion <code>State-&gt;Counter++</code> mit der Spezifikation: „The type is uint32. After 0xFF&#x27;FF&#x27;FF&#x27;FF, the next value is 0.“.\n</li><li><strong>Aktivitätsbereich / Kontextmarkierung:</strong> Oben links angeordneter Verweis bzw. Aktivitätssymbol <code>E2E_P07Protect()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Kontrollfluss führt direkt zur Aktion <code>State-&gt;Counter++</code>, in der der Zählerwert inkrementiert wird. Beim Erreichen des Maximalwerts <code>0xFFFFFFFF</code> (uint32) erfolgt ein arithmetischer Überlauf (Wrap-Around) auf <code>0</code>.\n</li><li>Direkter Übergang zum Endknoten der Teilaktivität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00494]</code>. Entwickler müssen sicherstellen, dass das Feld <code>Counter</code> als vorzeichenloser 32-Bit-Ganzzahltyp (<code>uint32</code>) realisiert wird und der Überlauf modulo 2^32 definiert auf 0 zurückspringt, ohne dass es zu arithmetischen Ausnahmen oder Begrenzungen (Sättigung) kommt.</p>"}, {"id": "FIG-5f7752d760f5d8f7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Kontext der AUTOSAR-E2E-Protokollspezifikation (End-to-End Communication Protection Library). Das Diagramm spezifiziert den detaillierten Teilschritt „Increment Counter“ innerhalb der Ablauffunktionen <code>E2E_P07Protect()</code> und <code>E2E_P07Forward()</code> für das E2E-Profil 7.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Initialknoten &amp; Endknoten:</strong> Startpunkt (Initial Node) und Terminierungspunkt (Activity Final Node) der Aktivität.\n</li><li><strong>Aktion:</strong> <code>State-&gt;Counter++</code> repräsentiert die Modifikation des Zählerzustands in der Zustandsstruktur <code>E2E_P07ProtectStateType</code>.\n</li><li><strong>Kommentar/Notiz:</strong> Assoziierte Notiz an der Aktion <code>State-&gt;Counter++</code> mit der Spezifikation: „The type is uint32. After 0xFF&#x27;FF&#x27;FF&#x27;FF, the next value is 0.“.\n</li><li><strong>Aktivitätsbereich / Kontextmarkierung:</strong> Oben links angeordneter Verweis bzw. Aktivitätssymbol <code>E2E_P07Protect()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Kontrollfluss führt direkt zur Aktion <code>State-&gt;Counter++</code>, in der der Zählerwert inkrementiert wird. Beim Erreichen des Maximalwerts <code>0xFFFFFFFF</code> (uint32) erfolgt ein arithmetischer Überlauf (Wrap-Around) auf <code>0</code>.\n</li><li>Direkter Übergang zum Endknoten der Teilaktivität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00494]</code>. Entwickler müssen sicherstellen, dass das Feld <code>Counter</code> als vorzeichenloser 32-Bit-Ganzzahltyp (<code>uint32</code>) realisiert wird und der Überlauf modulo 2^32 definiert auf 0 zurückspringt, ohne dass es zu arithmetischen Ausnahmen oder Begrenzungen (Sättigung) kommt.</p>"}], "trans": [{"from": "FIG-43d73a9ef2920dba", "to": "FIG-5f7752d760f5d8f7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
